widget.solution:
def auc_by_ranks(y, p):
    # share of (positive, negative) pairs where the positive scores higher; ties count half
    pos = [s for s, t in zip(p, y) if t == 1]
    neg = [s for s, t in zip(p, y) if t == 0]
    wins = 0.0
    for a in pos:
        for b in neg:
            if a > b:
                wins += 1
            elif a == b:
                wins += 0.5
    return round(wins / (len(pos) * len(neg)), 4)
